class Solution:
 def countAsterisks(self, s):
  outside=True; count=0
  for ch in s:
   if ch=='|': outside=not outside
   elif ch=='*' and outside: count+=1
  return count

class Solution:
 def checkXMatrix(self, grid):
  n=len(grid)
  for i in range(n):
   for j in range(n):
    if i==j or i+j==n-1:
     if grid[i][j]==0: return False
    elif grid[i][j]!=0: return False
  return True

class Solution:
 def decodeMessage(self, key, message):
  mapping={}; nxt=ord('a')
  for ch in key:
   if ch!=' ' and ch not in mapping:
    mapping[ch]=chr(nxt); nxt+=1
  return ''.join(' ' if ch==' ' else mapping[ch] for ch in message)

class Solution:
 def evaluateTree(self, root):
  if root.val in (0,1): return bool(root.val)
  left=self.evaluateTree(root.left); right=self.evaluateTree(root.right)
  return left or right if root.val==2 else left and right

class Solution:
 def fillCups(self, amount):
  return max(max(amount),(sum(amount)+1)//2)

from collections import Counter
class Solution:
 def numberOfPairs(self, nums):
  pairs=sum(v//2 for v in Counter(nums).values())
  return [pairs,len(nums)-2*pairs]

class Solution:
 def repeatedCharacter(self, s):
  seen=set()
  for c in s:
   if c in seen: return c
   seen.add(c)

from collections import defaultdict
class Solution:
 def mergeSimilarItems(self, items1, items2):
  weights=defaultdict(int)
  for v,w in items1+items2: weights[v]+=w
  return [[v,weights[v]] for v in sorted(weights)]
